	up, err := s.UpdateCustomer(a.ID, c1.ID, func(c *Customer) error {
		c.Email = "jane.doe@example.com"
		c.Metadata = map[string]string{"crm": "42"}
		return nil
	})
	if err != nil || up.Email != "jane.doe@example.com" {
		t.Fatalf("update = %+v, %v", up, err)
