// customerRetention is how long after deletion a customer can be restored; PurgeDeletedCustomers removes it after that.
const customerRetention = 30 * 24 * time.Hour

// DeleteCustomer removes a customer for good, at once. The API deletes with SoftDeleteCustomer instead; this is for
// undoing a customer that was just created.
func (s *Store) DeleteCustomer(orgID, id string) error {
	s.mu.Lock()
	defer s.mu.Unlock()
	c, ok := s.customers[id]
	if !ok || c.OrgID != orgID {
		return ErrNotFound
	}
	s.removeCustomer(id, c)
	return nil
}

// SoftDeleteCustomer marks a customer deleted at now. It is hidden from the organization until it is restored or purged,
// and its email address is free again. A customer with a subscription that is not canceled cannot be deleted.
func (s *Store) SoftDeleteCustomer(orgID, id string, now time.Time) error {
	s.mu.Lock()
	defer s.mu.Unlock()
	c, ok := s.customers[id]
	if !ok || c.OrgID != orgID || c.DeletedAt != nil {
		return ErrNotFound
	}
	for _, sub := range s.subs {
		if sub.CustomerID == id && sub.Status != Canceled {
			return ErrHasActiveSubscriptions
		}
	}
	at := now.UTC()
	c.DeletedAt = &at
	s.customers[id] = c
	if s.customersByEmail[normEmail(c.Email)] == id {
		delete(s.customersByEmail, normEmail(c.Email))
	}
	return nil
}

// RestoreCustomer undoes a soft delete made less than 30 days before now. It fails with ErrEmailTaken when another
// customer now uses the customer's email address.
func (s *Store) RestoreCustomer(orgID, id string, now time.Time) (Customer, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	c, ok := s.customers[id]
	if !ok || c.OrgID != orgID || c.DeletedAt == nil || now.Sub(*c.DeletedAt) > customerRetention {
		return Customer{}, ErrNotFound
	}
	key := normEmail(c.Email)
	if other, ok := s.customersByEmail[key]; ok && other != id {
		return Customer{}, ErrEmailTaken
	}
	c.DeletedAt = nil
	s.customers[id] = c
	s.customersByEmail[key] = id
	return copyCustomer(c), nil
}

// PurgeDeletedCustomers removes the customers deleted more than 30 days before now, for good, and returns how many it
// removed. Their invoices keep no customer.
func (s *Store) PurgeDeletedCustomers(now time.Time) int {
	s.mu.Lock()
	defer s.mu.Unlock()
	n := 0
	for id, c := range s.customers {
		if c.DeletedAt != nil && now.Sub(*c.DeletedAt) > customerRetention {
			s.removeCustomer(id, c)
			n++
		}
	}
	return n
}

// removeCustomer forgets a customer and its email address. The caller holds the lock.
func (s *Store) removeCustomer(id string, c Customer) {
	delete(s.customers, id)
	if s.customersByEmail[normEmail(c.Email)] == id {
		delete(s.customersByEmail, normEmail(c.Email))
	}
}

func copyCustomer(c Customer) Customer {
	if c.Metadata != nil {
		m := make(map[string]string, len(c.Metadata))
		for k, v := range c.Metadata {
			m[k] = v
		}
		c.Metadata = m
	}
	if c.DeletedAt != nil {
		t := *c.DeletedAt
		c.DeletedAt = &t
	}
	return c
}

