func TestSoftDeleteAndRestoreCustomer(t *testing.T) {
	s := New()
	a, b := newOrg(t, s, "A"), newOrg(t, s, "B")
	jane, _ := s.CreateCustomer(a.ID, "Jane", "jane@example.com", t0)
	p, _ := s.CreatePlan(Plan{OrgID: a.ID, Name: "Pro", Currency: money.USD, UnitAmount: 2000, Interval: Monthly}, t0)
	sub, _ := s.CreateSubscription(Subscription{OrgID: a.ID, CustomerID: jane.ID, PlanID: p.ID, Quantity: 1, Status: Active,
		StartedAt: t0, CurrentPeriodStart: t0, CurrentPeriodEnd: t0.AddDate(0, 1, 0)}, t0)
	del := t0.Add(time.Hour)
	if err := s.SoftDeleteCustomer(a.ID, jane.ID, del); !errors.Is(err, ErrHasActiveSubscriptions) {
		t.Fatalf("deleted with an active subscription: %v", err)
	}
	if _, err := s.UpdateSubscription(a.ID, sub.ID, func(x *Subscription) error { x.Status = Canceled; return nil }); err != nil {
		t.Fatal(err)
	}
	if err := s.SoftDeleteCustomer(b.ID, jane.ID, del); !errors.Is(err, ErrNotFound) {
		t.Fatalf("deleted through another org: %v", err)
	}
	if err := s.SoftDeleteCustomer(a.ID, jane.ID, del); err != nil {
		t.Fatal(err)
	}
	if err := s.SoftDeleteCustomer(a.ID, jane.ID, del); !errors.Is(err, ErrNotFound) {
		t.Fatalf("deleted twice: %v", err)
	}
	if _, ok := s.Customer(a.ID, jane.ID); ok {
		t.Fatal("deleted customer still visible")
	}
	if _, ok := s.FindCustomerByEmail(a.ID, "jane@example.com"); ok {
		t.Fatal("deleted customer found by email")
	}
	if got := s.Customers(a.ID); len(got) != 0 {
		t.Fatalf("Customers = %+v", got)
	}
	if got := s.SearchCustomers(a.ID, "jane"); len(got) != 0 {
		t.Fatalf("SearchCustomers = %+v", got)
	}
	if got, ok := s.CustomerIncludingDeleted(a.ID, jane.ID); !ok || got.DeletedAt == nil || !got.DeletedAt.Equal(del) {
		t.Fatalf("CustomerIncludingDeleted = %+v, %v", got, ok)
	}
	if got := s.CustomersIncludingDeleted(a.ID); len(got) != 1 {
		t.Fatalf("CustomersIncludingDeleted = %+v", got)
	}
	inv := Invoice{OrgID: a.ID, CustomerID: jane.ID, Currency: money.USD, Lines: []Line{{Description: "x", Quantity: 1, UnitAmount: 100}}}
	if _, err := s.CreateInvoice(inv, del); !errors.Is(err, ErrNotFound) {
		t.Fatalf("invoice for a deleted customer: %v", err)
	}
	if _, err := s.CreateSubscription(Subscription{OrgID: a.ID, CustomerID: jane.ID, PlanID: p.ID, Quantity: 1, Status: Active,
		StartedAt: t0, CurrentPeriodStart: t0, CurrentPeriodEnd: t0.AddDate(0, 1, 0)}, del); !errors.Is(err, ErrNotFound) {
		t.Fatalf("subscription for a deleted customer: %v", err)
	}
	if _, err := s.UpdateCustomer(a.ID, jane.ID, func(c *Customer) error { c.Name = "Jane 2"; return nil }); !errors.Is(err, ErrNotFound) {
		t.Fatalf("update of a deleted customer: %v", err)
	}

	// The deleted customer's email address is free, and the state keeps that after a round trip.
	s2, err := FromState(s.Export())
	if err != nil {
		t.Fatal(err)
	}
	if _, err := s2.CreateCustomer(a.ID, "Jane 2", "Jane@example.com", del); err != nil {
		t.Fatalf("email of a deleted customer is taken after FromState: %v", err)
	}
	jane2, err := s.CreateCustomer(a.ID, "Jane 2", "jane@example.com", del)
	if err != nil {
		t.Fatalf("email of a deleted customer: %v", err)
	}
	if _, err := s.RestoreCustomer(a.ID, jane.ID, del); !errors.Is(err, ErrEmailTaken) {
		t.Fatalf("restore with the email in use: %v", err)
	}
	if err := s.DeleteCustomer(a.ID, jane2.ID); err != nil {
		t.Fatal(err)
	}
	if _, err := s.RestoreCustomer(a.ID, jane.ID, del.AddDate(0, 0, 30).Add(time.Second)); !errors.Is(err, ErrNotFound) {
		t.Fatalf("restore after 30 days: %v", err)
	}
	if _, err := s.RestoreCustomer(a.ID, jane.ID, del.Add(time.Hour)); err != nil {
		t.Fatal(err)
	}
	got, err := s.RestoreCustomer(b.ID, jane.ID, del)
	if !errors.Is(err, ErrNotFound) {
		t.Fatalf("restored through another org: %v %+v", err, got)
	}
	if got, ok := s.Customer(a.ID, jane.ID); !ok || got.DeletedAt != nil || got.Email != "jane@example.com" {
		t.Fatalf("restored customer = %+v, %v", got, ok)
	}
	if _, err := s.RestoreCustomer(a.ID, jane.ID, del); !errors.Is(err, ErrNotFound) {
		t.Fatalf("restore of a customer that is not deleted: %v", err)
	}
}

func TestPurgeDeletedCustomers(t *testing.T) {
	s := New()
	a := newOrg(t, s, "A")
	old, _ := s.CreateCustomer(a.ID, "Old", "old@example.com", t0)
	recent, _ := s.CreateCustomer(a.ID, "Recent", "recent@example.com", t0)
	live, _ := s.CreateCustomer(a.ID, "Live", "live@example.com", t0)
	if err := s.SoftDeleteCustomer(a.ID, old.ID, t0); err != nil {
		t.Fatal(err)
	}
	if err := s.SoftDeleteCustomer(a.ID, recent.ID, t0.AddDate(0, 0, 20)); err != nil {
		t.Fatal(err)
	}
	if n := s.PurgeDeletedCustomers(t0.AddDate(0, 0, 30)); n != 0 {
		t.Fatalf("purged 30 days after the deletion: %d", n)
	}
	if n := s.PurgeDeletedCustomers(t0.AddDate(0, 0, 31)); n != 1 {
		t.Fatalf("purged %d, want 1", n)
