func TestDeleteAndRestoreCustomer(t *testing.T) {
	e := apitest.New(t)
	jane := e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
	p := e.CreatePlan(e.Acme, "Team", "USD", "20.00")
	var sub store.Subscription
	e.MustDo(http.StatusCreated, "POST", "/v1/subscriptions", e.Acme.Key, map[string]any{"customer_id": jane.ID, "plan_id": p.ID}, &sub)
	if r := e.Do("DELETE", "/v1/customers/"+jane.ID, e.Acme.Key, nil); r.Code != http.StatusConflict || r.Map(t)["error"] != "has_active_subscriptions" {
		t.Fatalf("delete with an active subscription: %s", r)
	}
	e.MustDo(http.StatusOK, "POST", "/v1/subscriptions/"+sub.ID+"/cancel", e.Acme.Key, nil, nil)
	var inv struct {
		ID string `json:"id"`
	}
	e.MustDo(http.StatusCreated, "POST", "/v1/invoices", e.Acme.Key, map[string]any{"customer_id": jane.ID, "currency": "USD",
		"lines": []store.Line{{Description: "Setup", Quantity: 1, UnitAmount: 500}}}, &inv)

	e.Clock.Advance(time.Hour)
	deletedAt := e.Clock.Now()
	e.MustDo(http.StatusNoContent, "DELETE", "/v1/customers/"+jane.ID, e.Acme.Key, nil, nil)
	if n := len(e.Store.Events(e.Acme.ID, "customer.deleted")); n != 1 {
		t.Fatalf("customer.deleted events = %d", n)
	}
	if c, ok := e.Store.CustomerIncludingDeleted(e.Acme.ID, jane.ID); !ok || c.DeletedAt == nil || !c.DeletedAt.Equal(deletedAt) {
		t.Fatalf("stored customer = %+v, %v", c, ok)
	}
	if r := e.Do("DELETE", "/v1/customers/"+jane.ID, e.Acme.Key, nil); r.Code != http.StatusNotFound || r.Map(t)["error"] != "not_found" {
		t.Fatalf("delete twice: %s", r)
	}
	if r := e.Do("PATCH", "/v1/customers/"+jane.ID, e.Acme.Key, map[string]string{"name": "Jane 2"}); r.Code != http.StatusNotFound {
		t.Fatalf("patch deleted: %s", r)
	}
	if r := e.Do("GET", "/v1/customers/"+jane.ID, e.Acme.Key, nil); r.Code != http.StatusNotFound || r.Map(t)["error"] != "not_found" {
		t.Fatalf("get deleted: %s", r)
	}
	if r := e.Do("POST", "/v1/invoices", e.Acme.Key, map[string]any{"customer_id": jane.ID, "currency": "USD",
		"lines": []store.Line{{Description: "x", Quantity: 1, UnitAmount: 1}}}); r.Code != http.StatusNotFound || r.Map(t)["error"] != "not_found" {
		t.Fatalf("invoice for deleted customer: %s", r)
	}
	if r := e.Do("POST", "/v1/subscriptions", e.Acme.Key, map[string]any{"customer_id": jane.ID, "plan_id": p.ID}); r.Code != http.StatusNotFound || r.Map(t)["error"] != "not_found" {
		t.Fatalf("subscription for deleted customer: %s", r)
	}
	var page struct {
		Items []store.Customer `json:"items"`
	}
	for _, q := range []string{"", "?q=jane", "?email=jane@example.com"} {
		page.Items = nil
		e.MustDo(http.StatusOK, "GET", "/v1/customers"+q, e.Acme.Key, nil, &page)
		if len(page.Items) != 0 {
			t.Fatalf("GET /v1/customers%s = %+v", q, page.Items)
		}
	}
	r := e.MustDo(http.StatusOK, "GET", "/v1/customers/export.csv", e.Acme.Key, nil, nil)
	if rows, err := csv.NewReader(strings.NewReader(string(r.Body))).ReadAll(); err != nil || len(rows) != 1 {
		t.Fatalf("csv = %v, %v", rows, err)
	}

	// The invoice keeps its customer, marked deleted.
	var view struct {
		Customer *struct {
			ID, Name, Email string
			Deleted         bool
		} `json:"customer"`
	}
	e.MustDo(http.StatusOK, "GET", "/v1/invoices/"+inv.ID, e.Acme.Key, nil, &view)
	if view.Customer == nil || view.Customer.ID != jane.ID || view.Customer.Name != "Jane" || !view.Customer.Deleted {
		t.Fatalf("invoice customer = %+v", view.Customer)
	}

	// The email address is free, so a new customer can take it and the deleted one cannot be restored over it.
	e.Clock.Advance(time.Minute)
	jane2 := e.CreateCustomer(e.Acme, "Jane 2", "JANE@example.com")
	if r := e.Do("POST", "/v1/customers/"+jane.ID+"/restore", e.Acme.Key, nil); r.Code != http.StatusConflict || r.Map(t)["error"] != "email_taken" {
		t.Fatalf("restore with the email in use: %s", r)
	}
	e.MustDo(http.StatusNoContent, "DELETE", "/v1/customers/"+jane2.ID, e.Acme.Key, nil, nil)
	var restored store.Customer
	e.MustDo(http.StatusOK, "POST", "/v1/customers/"+jane.ID+"/restore", e.Acme.Key, nil, &restored)
	if restored.ID != jane.ID || restored.Email != "jane@example.com" || restored.DeletedAt != nil {
		t.Fatalf("restored = %+v", restored)
	}
	e.MustDo(http.StatusOK, "GET", "/v1/customers/"+jane.ID, e.Acme.Key, nil, &restored)
	if r := e.Do("POST", "/v1/customers/"+jane.ID+"/restore", e.Acme.Key, nil); r.Code != http.StatusNotFound {
		t.Fatalf("restore of a customer that is not deleted: %s", r)
	}

	// After 30 days a deleted customer cannot be restored.
	e.MustDo(http.StatusNoContent, "DELETE", "/v1/customers/"+jane.ID, e.Acme.Key, nil, nil)
	e.Clock.Advance(30*24*time.Hour + time.Second)
	if r := e.Do("POST", "/v1/customers/"+jane.ID+"/restore", e.Acme.Key, nil); r.Code != http.StatusNotFound || r.Map(t)["error"] != "not_found" {
		t.Fatalf("restore after 30 days: %s", r)
	}
	if r := e.Do("POST", "/v1/customers/"+jane.ID+"/restore", e.Globex.Key, nil); r.Code != http.StatusNotFound {
		t.Fatalf("restore through another org: %s", r)
	}
}

